// Bundled OurAirports subset (public domain): large + medium airports, generated by
// scripts/refresh-airports.mjs. Loaded lazily (about 1.1 MB of JSON) on map routes only.

import type { FeatureCollection, Point } from "geojson";

import { haversineNm, type LatLon } from "./geo";

export interface Airport {
  ident: string;
  iata?: string;
  name: string;
  type: "large" | "medium";
  lat: number;
  lon: number;
  elevFt?: number;
  country: string;
  region: string;
  municipality?: string;
  longestRwyFt?: number;
  surface?: string;
}

export interface AirportIndex {
  list: readonly Airport[];
  byIdent: ReadonlyMap<string, Airport>;
}

export function indexAirports(list: readonly Airport[]): AirportIndex {
  const byIdent = new Map<string, Airport>();
  for (const a of list) byIdent.set(a.ident.toUpperCase(), a);
  return { list, byIdent };
}

let pending: Promise<AirportIndex> | null = null;

/** Load the bundled airport list once (dynamic import keeps it out of other routes). */
export function loadAirports(): Promise<AirportIndex> {
  pending ??= import("@/assets/data/airports-major.json")
    .then((mod) => indexAirports((mod as { default: Airport[] }).default))
    .catch((err: unknown) => {
      pending = null;
      throw err;
    });
  return pending;
}

export function findAirport(index: AirportIndex | null, ident: string | null | undefined) {
  if (!index || !ident) return null;
  return index.byIdent.get(ident.trim().toUpperCase()) ?? null;
}

/** Airports within `radiusNm` of a point, nearest first. */
export function nearbyAirports(
  list: readonly Airport[],
  at: LatLon,
  radiusNm: number,
): { airport: Airport; distanceNm: number }[] {
  // Cheap latitude prefilter before the great-circle distance (1° lat ≈ 60 nm).
  const dLat = radiusNm / 60;
  const out: { airport: Airport; distanceNm: number }[] = [];
  for (const airport of list) {
    if (Math.abs(airport.lat - at.lat) > dLat) continue;
    const distanceNm = haversineNm(at, airport);
    if (distanceNm <= radiusNm) out.push({ airport, distanceNm });
  }
  return out.sort((a, b) => a.distanceNm - b.distanceNm);
}

export function airportsGeoJson(list: readonly Airport[]): FeatureCollection<Point> {
  return {
    type: "FeatureCollection",
    features: list.map((a) => ({
      type: "Feature",
      geometry: { type: "Point", coordinates: [a.lon, a.lat] },
      properties: { ident: a.ident, type: a.type },
    })),
  };
}
